CREATE TABLE market_imports (id TEXT PRIMARY KEY, source TEXT NOT NULL CHECK(source IN ('file','api')), provider TEXT NOT NULL, filename TEXT NOT NULL, sha256 TEXT NOT NULL UNIQUE, rows INTEGER NOT NULL DEFAULT 0, success INTEGER NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0, errors INTEGER NOT NULL DEFAULT 0, imported_by TEXT, created_at TEXT NOT NULL, status TEXT NOT NULL, error_details TEXT NOT NULL DEFAULT '[]', agent_counts TEXT NOT NULL DEFAULT '{}', unmatched_details TEXT NOT NULL DEFAULT '[]');
CREATE TABLE market_events (id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('sale','listing','withdrawn')), address TEXT NOT NULL, address_key TEXT NOT NULL, lot_plan TEXT, suburb TEXT, postcode TEXT, price INTEGER, event_date TEXT, agency TEXT, agent TEXT, beds REAL, baths REAL, cars REAL, land REAL, import_id TEXT NOT NULL REFERENCES market_imports(id), property_id TEXT REFERENCES properties(id), raw TEXT NOT NULL, UNIQUE(provider,provider_id,kind));
CREATE INDEX market_events_property ON market_events(property_id);
CREATE TABLE property_ownership (property_id TEXT PRIMARY KEY REFERENCES properties(id), owner_names TEXT NOT NULL DEFAULT '', last_sale_price INTEGER, last_sale_date TEXT, source TEXT NOT NULL, import_id TEXT NOT NULL REFERENCES market_imports(id), updated_at TEXT NOT NULL);
ALTER TABLE market_items ADD COLUMN event_id TEXT;
CREATE UNIQUE INDEX market_items_event_owner ON market_items(event_id,owner_id) WHERE event_id IS NOT NULL;
